"""Discover output and read sequence are frozen against goldens generated by the 74cf616 implementation."""
import json
import os
import pathlib
import unittest
from unittest.mock import patch

from agent_contribute import core
from tests.test_protocol import FakeGitHub
from tests.test_resolution import RepositoryGitHub, pr
from tests.test_schema_compatibility import FrozenClock

GOLDEN = pathlib.Path(os.environ.get('DISCOVER_GOLDEN_DIR', pathlib.Path(__file__).parent / 'fixtures' / 'discover'))
POLICY = {'schema_version': '0.1', 'agent_approved_labels': ['agent-ok'], 'label_authority': 'repository-label-permission'}


def scenarios():
    def failing(*keys, **kwargs):
        client = FakeGitHub(**kwargs)
        client.failed.update(keys)
        return client
    def fork(failed=(), prs=()):
        client = RepositoryGitHub()
        client.failed.update(failed)
        client.repos['person/photos'].prs = list(prs)
        return client
    return {
        'plain': ('acme/photos', FakeGitHub()),
        'policy_overlap': ('acme/photos', FakeGitHub(POLICY, ['agent-ok'], [
            {'number': 30, 'title': 'Fix thumbnail bounds', 'body': 'Fixes #12',
             'html_url': 'https://github.com/acme/photos/pull/30', 'head': None}])),
        'labels_fail': ('acme/photos', failing('/labels')),
        'issue_list_fail': ('acme/photos', failing('/issues?')),
        'tree_fail': ('acme/photos', failing('/git/trees/')),
        'commit_fail': ('acme/photos', failing('/commits/main')),
        'fork': ('person/photos', fork(prs=[pr('person/photos', 7, 'Fixes #12')])),
        'fork_target_fail': ('person/photos', fork(failed={'repos/person/photos/pulls?state=open&per_page=100&page=1'})),
        'metadata_fail': ('person/photos', fork(failed={'repos/person/photos'})),
    }


class DiscoverGoldenTests(unittest.TestCase):
    def test_discover_output_and_reads_match_legacy_goldens(self):
        with patch.object(core.dt, 'datetime', FrozenClock):
            for name, (repository, client) in scenarios().items():
                with self.subTest(name=name):
                    result = core.discover(repository, client, invitation_protocol='tipjar-invitation/1')
                    actual = json.dumps({'result': result, 'calls': client.calls}, indent=2, ensure_ascii=True) + '\n'
                    path = GOLDEN / (name + '.json')
                    if os.environ.get('UPDATE_GOLDEN'):
                        path.write_text(actual, encoding='utf-8')
                    self.assertEqual(actual, path.read_text(encoding='utf-8'))


if __name__ == '__main__':
    unittest.main()
